SELECT '2_bridge' as q_type, e.id AS entry_id, e.headword, e.headword_norm, e.root, e.definitions_text, e.translation_en, d.name_ar, d.source_type FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.id IN (SELECT rowid FROM entries_translations_fts WHERE entries_translations_fts MATCH 'translation_en:\"backlog\"');

SELECT '3_fts' as q_type, e.id AS entry_id, e.headword, e.headword_norm, e.root, e.definitions_text, d.name_ar, d.source_type FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.id IN (SELECT rowid FROM entries_fts WHERE entries_fts MATCH '\"متراكمات\" OR \"متاخرات\"' ORDER BY bm25(entries_fts) LIMIT 20);
" > /workspace/query_results.json

sqlite3 -json /data/arabic_dict.db "
SELECT '1_lookup' as q_type, e.id AS entry_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.name_ar, d.source_type, d.period FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('ركام', 'الركام', 'متاخرات', 'المتاخرات', 'متاخرات عمل', 'متاخرات العمل', 'اعمال غير منجزة', 'الاعمال غير المنجزة') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;
